extra_css:
/* Salt Mirror surfaces: translucent brine-glass panels over hexagonal salt-crust facets with a crisp horizon rim reflection;
   hover brightens the crystalline salt edge. Headings shimmer like twilight sky mirrored in still water.
   Scoped to own surfaces only. */
html[data-atmo="saltflat"] .card, html[data-atmo="saltflat"] .panel, html[data-atmo="saltflat"] .gx-card {
  background: radial-gradient(130% 80% at 50% 0%, rgba(143,212,255,.08), transparent 62%), linear-gradient(180deg, rgba(22,33,51,.88), rgba(7,11,18,.94));
  backdrop-filter: blur(10px); -webkit-backdrop-filter: blur(10px);
  box-shadow: inset 0 1px 0 rgba(196,233,255,.30), inset 0 0 0 1px rgba(143,212,255,.22), 0 18px 46px rgba(0,0,0,.76);
  transition: box-shadow .4s ease, transform .5s cubic-bezier(.2,1,.3,1), background .6s ease; }
html[data-atmo="saltflat"] .card:hover, html[data-atmo="saltflat"] .gx-card:hover {
  transform: translateY(-2px);
  background: radial-gradient(130% 80% at 50% 0%, rgba(196,233,255,.14), transparent 65%), linear-gradient(180deg, rgba(28,42,64,.91), rgba(9,14,24,.95));
  box-shadow: inset 0 1px 0 rgba(224,244,255,.52), inset 0 0 0 1px rgba(143,212,255,.48), 0 0 28px rgba(143,212,255,.14), 0 22px 54px rgba(0,0,0,.8); }
html[data-atmo="saltflat"] h1, html[data-atmo="saltflat"] h2 { background: linear-gradient(180deg, #ffffff, #cce8ff 50%, #7aaad4); -webkit-background-clip: text; background-clip: text; color: transparent; }
html[data-atmo="saltflat"] h1 { filter: drop-shadow(0 2px 14px rgba(0,0,0,.9)) drop-shadow(0 0 2px rgba(0,0,0,.85)); }

